#pragma once
void BackgroundIntegrationPolicy() {
    Config c,parsed;std::string error;AppRule running{2,false,false,"C:\\Private\\render.exe"};running.targets={"A","disconnected"};c.rules={running};
    c.nicknames["A"]="Private nickname";c.automatic=true;c.monitors["A"].hardware=true;Profile profile;profile.name="Work";profile.policy=c;c.profiles={profile};
    Check(Parse(Serialize(c),parsed,error)&&parsed.sourceSchema==5&&parsed.rules[0].targets==running.targets&&parsed.profiles[0].policy.rules[0].kind==2,"schema5 background rules roundtrip with profiles names and disconnected stable assignments");
    auto roundtrip=Serialize(parsed);DisarmImportedConfig(parsed);Check(!parsed.automatic&&!parsed.monitors["A"].hardware&&!parsed.profiles[0].policy.automatic&&!parsed.profiles[0].policy.monitors["A"].hardware&&parsed.rules[0].targets==running.targets,"background import preserves preferences and revokes base/profile automation and hardware");
    Config old;Check(Parse("version=4\nrule.0=0|0|0|433a5c612e657865\n",old,error)&&old.rules[0].enabled&&old.rules[0].targets.empty()&&old.rules[0].kind==0,"schema4 foreground default migration remains enabled with original attribution");
    auto preserved=Serialize(c);Check(!Commit(c,c,[](const std::string&){return false;})&&Serialize(c)==preserved,"schema5 failed store leaves rules and permissions unchanged");
    for(auto rule:std::vector<AppRule>{AppRule{2,false,false,"C:\\a.exe"},AppRule{3,true,false,"C:\\a.exe"},AppRule{2,true,false,"C:\\a.exe",true,{"A"}},AppRule{0,false,false,"C:\\a.exe",true,{"A"}},AppRule{2,false,false,"C:\\a.exe",true,{"@span"}}}){
        Config bad;bad.rules={rule};Check(!Parse(Serialize(bad),parsed,error),"invalid kind and implicit or conflicting target scope rejected");}
    auto legacyWithExtended=roundtrip;legacyWithExtended.replace(0,9,"version=4");Check(!Parse(legacyWithExtended,parsed,error),"schema4 cannot smuggle extended rule kind through schema5 fields");
    Controller p;p.config.automatic=true;p.config.media=false;p.config.timeout=5;running.targets={"A"};p.config.rules={running};p.Topology({"A","B","C"},1);p.SelectPolicy(1,0);
    p.Manual("B",2,true,-1);auto peer=p.nodes.at("B"),idlePeer=p.nodes.at("C");
    Check(p.background.Apply({p.backgroundEpoch,100,{BackgroundMatch::Present}},100),"background injected present accepted");p.Tick(100,{});
    Check(p.nodes.at("A").state==State::Suppressed&&p.Explain("A",{},100).primary==Reason::Background&&FeatureNodeSame(peer,p.nodes.at("B"))&&FeatureNodeSame(idlePeer,p.nodes.at("C")),"background without foreground inhibits only explicit A and preserves sticky and idle peers");
    p.background.Apply({p.backgroundEpoch,101,{BackgroundMatch::Absent}},101);p.Tick(101,{});Check(p.nodes.at("A").last==101&&p.nodes.at("A").state==State::Desktop&&FeatureNodeSame(peer,p.nodes.at("B")),"fresh absence releases A with fresh idle boundary and preserves B");
    p.Tick(5100,{});Check(!Running(p.nodes.at("A").state),"fresh background boundary prevents immediate activation from old history");p.Tick(5101,{});Check(Running(p.nodes.at("A").state),"target activates after full fresh idle interval");
    p.background.Apply({p.backgroundEpoch,6000,{BackgroundMatch::Present}},6000);p.Tick(6000,{});p.background.Apply({p.backgroundEpoch,7000,{BackgroundMatch::Unknown}},7000);p.Tick(11000,{});Check(p.nodes.at("A").state==State::Suppressed,"last positive remains through five-second grace boundary");p.Tick(11001,{});Check(p.nodes.at("A").state==State::Desktop&&p.nodes.at("A").last==11001&&p.background.Uncertain(0,11001),"expired unknown contribution releases with fresh target interval and visible uncertainty");
    Check(p.KeepAwake("A",12000,1),"overlapping lease fixture");auto deadline=p.leases.at("A").deadline;p.background.Apply({p.backgroundEpoch,12001,{BackgroundMatch::Present}},12001);p.Tick(12001,{});p.background.Apply({p.backgroundEpoch,12002,{BackgroundMatch::Absent}},12002);p.Tick(12002,{});
    Check(p.leases.at("A").deadline==deadline&&p.Explain("A",{},12002).primary==Reason::KeepAwake,"background removal never cancels independent keep-awake lease");
    p.Manual("A",12003,true,-1);auto manual=p.nodes.at("A");p.background.Apply({p.backgroundEpoch,12004,{BackgroundMatch::Present}},12004);p.Tick(12004,{});Check(FeatureNodeSame(manual,p.nodes.at("A")),"background transitions preserve manual sticky authority");
    Controller edit;edit.config.automatic=true;edit.config.media=false;edit.config.timeout=3600;running.targets={"A"};auto b=running;b.targets={"B"};edit.config.rules={running,b};edit.Topology({"A","B","C"},1);edit.SelectPolicy(1,0);edit.background.Apply({edit.backgroundEpoch,2000,{BackgroundMatch::Present,BackgroundMatch::Present}},2000);edit.Tick(2000,{});
    auto stableB=edit.nodes.at("B"),stableC=edit.nodes.at("C");auto oldEpoch=edit.backgroundEpoch;edit.config.rules.erase(edit.config.rules.begin());Check(edit.SelectPolicy(2001,0),"rules-only edit recognized without general controller reset");edit.Tick(2001,{});
    Check(edit.backgroundEpoch!=oldEpoch&&!edit.background.Apply({oldEpoch,2001,{BackgroundMatch::Present}},2001)&&FeatureNodeSame(stableB,edit.nodes.at("B"))&&FeatureNodeSame(stableC,edit.nodes.at("C"))&&edit.nodes.at("A").last==2001,"removing A rejects late observations while retaining unchanged B rule state and C history");
    auto a=edit.nodes.at("A");edit.config.rules.push_back(b);edit.SelectPolicy(2002,0);edit.Tick(2002,{});Check(FeatureNodeSame(a,edit.nodes.at("A")),"overlapping B rule edit never resets A");
    edit.InvalidateBackground();edit.Tick(2003,{});Check(!edit.BackgroundActive("B",2003)&&edit.nodes.at("B").last==2003,"session epoch revokes prior background authority with fresh boundary");
    Profile same;same.name="Identical policy";same.policy=edit.config;edit.config.profiles.push_back(same);auto epoch=edit.backgroundEpoch;edit.config.manualProfile=same.name;edit.SelectPolicy(2004,0);
    Check(edit.activeProfile==same.name&&edit.backgroundEpoch!=epoch&&!edit.background.Apply({epoch,2004,{BackgroundMatch::Present,BackgroundMatch::Present}},2004),"profile switch with identical policy still rejects previous-profile observations");
    puts("POLICY background integration PASS: schema5 migration/disarming, explicit scopes, transactional failure, targeted boundaries, independent inhibitors/manual authority and epoch edits");
}
